function solve(input) {
    let winner = 0;
    let lead = input.plays[0].s;
    let highest = input.plays[0].r;

    let idx = 0;
    const len = input.plays.length;
    const step = len > 1 ? 1 : 0;

    do {
        idx += step;
        const play = input.plays[idx];
        if (play.s === lead && play.r > highest) {
            highest = play.r;
            winner = idx;
        }
    } while (idx < len - 1);

    return winner;
}

