  for (const [r] of input.cards) cnt.set(r, (cnt.get(r) || 0) + 1);
  const shape = [...cnt.values()].sort((a, b) => b - a).join('');
  const distinct = [...cnt.keys()].sort((a, b) => a - b);
  let straight = false;
